/** The tables of the database, as Sequelize models. They reflect the database: never sync them with it. */
import { DataTypes, literal, type Model, type ModelStatic, type Sequelize } from 'sequelize'

/** The model of every table */
export interface Models {
  things: ModelStatic<Model>
  kinds: ModelStatic<Model>
  order: ModelStatic<Model>
  entries: ModelStatic<Model>
  empties: ModelStatic<Model>
}

/** Defines the model of every table on `sequelize`. */
export function defineModels(sequelize: Sequelize): Models {
  /** The "things" table. */
  const things = sequelize.define(
    'things',
    {
      id: { type: DataTypes.UUID, primaryKey: true, allowNull: false, defaultValue: DataTypes.UUIDV4 },
      token: { type: DataTypes.UUID, allowNull: false },
      small: { type: DataTypes.SMALLINT, allowNull: false },
      num: { type: DataTypes.INTEGER, allowNull: true },
      big: { type: DataTypes.BIGINT, allowNull: false },
      price: { type: DataTypes.DECIMAL(10, 2), allowNull: false },
      r: { type: DataTypes.REAL, allowNull: false },
      d: { type: DataTypes.DOUBLE, allowNull: true },
      flag: { type: DataTypes.BOOLEAN, allowNull: false, defaultValue: true },
      born: { type: DataTypes.DATEONLY, allowNull: false },
      opens: { type: DataTypes.TIME, allowNull: false },
      opensTz: { type: DataTypes.TIME, allowNull: false, field: 'opens_tz' },
      at: { type: DataTypes.DATE, allowNull: false },
      atTz: { type: DataTypes.DATE, allowNull: false, field: 'at_tz' },
      bin: { type: DataTypes.BLOB, allowNull: false },
      data: { type: DataTypes.JSONB, allowNull: false },
      plain: { type: DataTypes.JSON, allowNull: true },
      feeling: { type: DataTypes.ENUM('sad', 'ok', 'very happy'), allowNull: false },
      tags: { type: DataTypes.ARRAY(DataTypes.TEXT), allowNull: false },
      numbers: { type: DataTypes.ARRAY(DataTypes.INTEGER), allowNull: true },
      // TODO: "inet" has no Sequelize type here; it is mapped as text
      ip: { type: DataTypes.TEXT, allowNull: true },
      // TODO: "interval" has no Sequelize type here; it is mapped as text
      span: { type: DataTypes.TEXT, allowNull: true },
      code: { type: DataTypes.CHAR(5), allowNull: false },
      note: { type: DataTypes.TEXT, allowNull: true },
      changed: { type: DataTypes.DATE, allowNull: true, defaultValue: literal('CURRENT_TIMESTAMP') },
      // TODO: total is computed by the database (price * 2); Sequelize cannot say so, and the repositories never write it
      total: { type: DataTypes.DECIMAL(12, 2), allowNull: true },
    },
    { tableName: 'things', timestamps: false },
  )

  /** The "kinds" table. */
  const kinds = sequelize.define(
    'kinds',
    {
      code: { type: DataTypes.STRING(10), primaryKey: true, allowNull: false },
      day: { type: DataTypes.DATEONLY, primaryKey: true, allowNull: false },
      label: { type: DataTypes.STRING(30), allowNull: true },
    },
    { tableName: 'kinds', timestamps: false },
  )

  /** The "Order" table. */
  // CHECK ("group" >= 0): Sequelize does not keep CHECK constraints; the services check them
  const order = sequelize.define(
    'Order',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false, field: 'Id' },
      user: { type: DataTypes.STRING(40), allowNull: false },
      group: { type: DataTypes.INTEGER, allowNull: false, defaultValue: 0 },
      customerName: { type: DataTypes.STRING(60), allowNull: false },
      class_: { type: DataTypes.TEXT, allowNull: true, field: 'class' },
      metadata: { type: DataTypes.TEXT, allowNull: true },
      date: { type: DataTypes.DATEONLY, allowNull: true },
      time: { type: DataTypes.TIME, allowNull: true },
      text: { type: DataTypes.STRING(20), allowNull: true },
      list: { type: DataTypes.TEXT, allowNull: true },
      str: { type: DataTypes.STRING(10), allowNull: true },
      int: { type: DataTypes.INTEGER, allowNull: true },
      dueDate: { type: DataTypes.DATEONLY, allowNull: false },
      closesAt: { type: DataTypes.TIME, allowNull: true },
      createdAt: { type: DataTypes.DATE, allowNull: true, defaultValue: literal('CURRENT_TIMESTAMP') },
      // TODO: (kind_code, kind_day) points to kinds; Sequelize keeps no foreign key of several columns
      kindCode: { type: DataTypes.STRING(10), allowNull: true, field: 'kind_code' },
      kindDay: { type: DataTypes.DATEONLY, allowNull: true, field: 'kind_day' },
      thingId: { type: DataTypes.UUID, allowNull: true, field: 'thing_id', references: { model: { tableName: 'things', schema: 'public' }, key: 'id' }, onDelete: 'SET NULL', onUpdate: 'NO ACTION' },
      parentId: { type: DataTypes.BIGINT, allowNull: true, references: { model: { tableName: 'Order', schema: 'public' }, key: 'Id' }, onDelete: 'NO ACTION', onUpdate: 'NO ACTION' },
    },
    {
      tableName: 'Order',
      timestamps: false,
      indexes: [
        { unique: true, fields: ['customerName'] },
      ],
    },
  )

  /** The "entries" table. */
  const entries = sequelize.define(
    'entries',
    {
      entryNo: { type: DataTypes.INTEGER, primaryKey: true, autoIncrement: true, allowNull: false, field: 'entry_no' },
      orderId: { type: DataTypes.BIGINT, allowNull: false, references: { model: { tableName: 'Order', schema: 'public' }, key: 'Id' }, onDelete: 'CASCADE', onUpdate: 'NO ACTION' },
      message: { type: DataTypes.STRING(200), allowNull: false },
    },
    { tableName: 'entries', schema: 'audit', timestamps: false },
  )

  /** The "empties" table. */
  const empties = sequelize.define(
    'empties',
    {
      id: { type: DataTypes.BIGINT, primaryKey: true, autoIncrement: true, allowNull: false },
      note: { type: DataTypes.TEXT, allowNull: true },
    },
    { tableName: 'empties', timestamps: false },
  )
  return { things, kinds, order, entries, empties }
}

