/** Repository of the "empties" table: reads and writes rows, and decides nothing. */
import { DatabaseError, ValidationError, type Model, type Transaction } from 'sequelize'
import type { Db } from '../database.js'
import { Empty } from '../entities/empty.js'
import { ConflictError } from '../errors.js'
import type { Page } from '../paging.js'

/** Where empties rows are kept. Services depend only on this interface. */
export interface EmptyRepository {
  findById(id: number): Promise<Empty | null>
  list(offset?: number, limit?: number): Promise<Page<Empty>>
  insert(entity: Empty): Promise<Empty>
  update(entity: Empty): Promise<Empty>
  delete(entity: Empty): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Empty): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Empty of an instance Sequelize read. */
function toEntity(instance: Model): Empty {
  const row = instance.get({ plain: true }) as Record<string, unknown>
  return Object.assign(new Empty(), {
    id: Number(row.id),
    note: row.note as string | null,
  })
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: Empty): Record<string, unknown> {
  const values: Record<string, unknown> = {
    id: entity.id,
    note: entity.note,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined))
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Empty): Record<string, unknown> {
  return {
    note: entity.note,
