/** Where things rows are kept. Services depend only on this interface. */
export interface ThingRepository {
  findById(id: string): Promise<Thing | null>
  list(offset?: number, limit?: number): Promise<Page<Thing>>
  insert(entity: Thing): Promise<Thing>
  update(entity: Thing): Promise<Thing>
  delete(entity: Thing): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Thing): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Thing of an instance Sequelize read. */
function toEntity(instance: Model): Thing {
  const row = instance.get({ plain: true }) as Record<string, unknown>
  return Object.assign(new Thing(), {
    id: row.id as string,
    token: row.token as string,
    small: row.small as number,
    num: row.num as number | null,
    big: Number(row.big),
    price: String(row.price),
    r: row.r as number,
    d: row.d as number | null,
    flag: row.flag as boolean,
    born: row.born as string,
    opens: row.opens as string,
    opensTz: row.opensTz as string,
    at: row.at as Date,
    atTz: row.atTz as Date,
    bin: row.bin as Buffer,
    data: row.data as unknown,
    plain: row.plain as unknown | null,
    feeling: row.feeling as string,
    tags: row.tags as string[],
    numbers: row.numbers as number[] | null,
    ip: row.ip as string | null,
    span: row.span as string | null,
    code: row.code as string,
    note: row.note as string | null,
    changed: row.changed as Date | null,
    total: row.total == null ? null : String(row.total),
  })
}

/** The values of a new row; those left undefined take the database's default. */
function insertValues(entity: Thing): Record<string, unknown> {
  const values: Record<string, unknown> = {
    id: entity.id,
    token: entity.token,
    small: entity.small,
    num: entity.num,
    big: entity.big,
    price: entity.price,
    r: entity.r,
    d: entity.d,
    flag: entity.flag,
    born: entity.born,
    opens: entity.opens,
    opensTz: entity.opensTz,
    at: entity.at,
    atTz: entity.atTz,
    bin: entity.bin,
    data: entity.data,
    plain: entity.plain,
    feeling: entity.feeling,
    tags: entity.tags,
    numbers: entity.numbers,
    ip: entity.ip,
    span: entity.span,
    code: entity.code,
    note: entity.note,
    changed: entity.changed,
  }
  return Object.fromEntries(Object.entries(values).filter(([, value]) => value !== undefined))
}

/** The values a change writes: not the key, nor what the database fills. */
function updateValues(entity: Thing): Record<string, unknown> {
  return {
    token: entity.token,
    small: entity.small,
    num: entity.num,
    big: entity.big,
    price: entity.price,
    r: entity.r,
    d: entity.d,
    flag: entity.flag,
    born: entity.born,
    opens: entity.opens,
    opensTz: entity.opensTz,
    at: entity.at,
    atTz: entity.atTz,
    bin: entity.bin,
    data: entity.data,
    plain: entity.plain,
    feeling: entity.feeling,
    tags: entity.tags,
    numbers: entity.numbers,
    ip: entity.ip,
    span: entity.span,
    code: entity.code,
    note: entity.note,
  }
}

/** Keeps things rows in the database, through Sequelize. It never commits: queries run in the transaction it was given. */
export class SqlThingRepository implements ThingRepository {
  constructor(
    private readonly db: Db,
    private readonly transaction: Transaction | null = null,
  ) {}

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Thing | null> {
    const row = await this.db.models.things.findOne({ where: { id }, transaction: this.transaction })
    return row === null ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Thing>> {
    const { rows, count } = await this.db.models.things.findAndCountAll({ order: [['id', 'ASC']], offset, limit, transaction: this.transaction })
    return { items: rows.map(toEntity), total: count, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Thing): Promise<Thing> {
    try {
      const row = await this.db.models.things.create(insertValues(entity), { transaction: this.transaction })
      await row.reload({ transaction: this.transaction })
      return Object.assign(entity, toEntity(row))
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Thing', `the database refused the change: ${error.message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Thing): Promise<Thing> {
    try {
      await this.db.models.things.update(updateValues(entity), { where: { id: entity.id }, transaction: this.transaction })
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Thing', `the database refused the change: ${error.message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Thing): Promise<void> {
    try {
      await this.db.models.things.destroy({ where: { id: entity.id }, transaction: this.transaction })
    } catch (error) {
      if (error instanceof DatabaseError || error instanceof ValidationError)
        throw new ConflictError('Thing', `the database refused the change: ${error.message}`)
      throw error
    }
  }
}

/** Keeps things rows in memory, for tests and for trying the services without a database. */
export class MemoryThingRepository implements ThingRepository {
  private readonly rows = new Map<string, Thing>()

  private visible(): Thing[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: string): Promise<Thing | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Thing>> {
    const rows = this.visible()
    return { items: rows.slice(offset, offset + limit), total: rows.length, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Thing): Promise<Thing> {
    if (entity.id === undefined) entity.id = randomUUID()
    if (entity.flag === undefined) entity.flag = true
    if (entity.changed === undefined) entity.changed = new Date()
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Thing): Promise<Thing> {
    this.rows.set(JSON.stringify(keyOf(entity)), entity)
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Thing): Promise<void> {
    this.rows.delete(JSON.stringify(keyOf(entity)))
  }
}

