export class EmptyService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "empties" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Empty | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Empty' })
    if (!creating) for (const name of Object.keys(values)) if (['id'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    if (errors.length > 0) throw new ValidationFailedError('Empty', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Empty | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Empty with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Empty> {
    const entity = await uow.empties.findById(id)
    if (entity === null) throw new NotFoundError('Empty', id)
    return entity
  }

  /** The Empty as services return it. */
  private static read(entity: Empty): EmptyRead {
    return { id: entity.id, note: entity.note }
  }

  /** Stores a new Empty after checking it. */
  async createEmpty(data: EmptyCreate): Promise<EmptyRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.empties.insert(Object.assign(new Empty(), values))
      return EmptyService.read(created)
    })
  }

  /** The Empty with this key; NotFoundError when there is none. */
  async getEmpty(id: number): Promise<EmptyRead> {
    return EmptyService.read(await this.find(this.uow, id))
  }

  /** A page of empties, by primary key. */
  async listEmpties(offset = 0, limit = 50): Promise<Page<EmptyRead>> {
    const page = await this.uow.empties.list(offset, limit)
