    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Entry' })
    if (!creating) for (const name of Object.keys(values)) if (['entryNo'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.orderId
      if (value == null) {
        if (creating || 'orderId' in values) errors.push({ field: 'orderId', message: 'is required' })
      }
    }
    {
      const value = values.message
      if (value == null) {
        if (creating || 'message' in values) errors.push({ field: 'message', message: 'is required' })
