    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Kind' })
    if (!creating) for (const name of Object.keys(values)) if (['code', 'day'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
