/** Operations on Order: what each one checks before it writes. */
import type { OrderCreate, OrderRead, OrderUpdate } from '../dtos/order.js'
import { Order } from '../entities/order.js'
import { ConflictError, NotFoundError, ValidationFailedError, type FieldError } from '../errors.js'
import type { Page } from '../paging.js'
import type { UnitOfWork } from '../unit-of-work.js'

/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['user', 'group', 'customerName', 'class_', 'metadata', 'date', 'time', 'text', 'list', 'str', 'int', 'dueDate', 'closesAt', 'kindCode', 'kindDay', 'thingId', 'parentId'])

/** Operations on Order. Each write runs in its own transaction. */
export class OrderService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "Order" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Order' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'createdAt'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.user
      if (value == null) {
        if (creating || 'user' in values) errors.push({ field: 'user', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 40) errors.push({ field: 'user', message: 'is longer than 40 characters' })
      }
    }
    {
      const value = values.group
      if (value == null) {
        if ('group' in values && !creating) errors.push({ field: 'group', message: 'cannot be empty' })
      } else {
        if (!(Number(value) >= 0)) errors.push({ field: 'group', message: 'must be >= 0' })
      }
    }
    {
      const value = values.customerName
      if (value == null) {
        if (creating || 'customerName' in values) errors.push({ field: 'customerName', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 60) errors.push({ field: 'customerName', message: 'is longer than 60 characters' })
      }
    }
    {
      const value = values.text
      if (value != null) {
        if (typeof value === 'string' && value.length > 20) errors.push({ field: 'text', message: 'is longer than 20 characters' })
      }
    }
    {
      const value = values.str
      if (value != null) {
        if (typeof value === 'string' && value.length > 10) errors.push({ field: 'str', message: 'is longer than 10 characters' })
      }
    }
    {
      const value = values.dueDate
      if (value == null) {
        if (creating || 'dueDate' in values) errors.push({ field: 'dueDate', message: 'is required' })
      }
    }
    {
      const value = values.kindCode
      if (value != null) {
        if (typeof value === 'string' && value.length > 10) errors.push({ field: 'kind_code', message: 'is longer than 10 characters' })
      }
    }
    {
      const thingId = 'thingId' in values ? values.thingId : current?.thingId
      if (thingId != null && (await uow.things.findById(thingId as string)) === null)
        errors.push({ field: 'thing_id', message: 'no Thing has this key' })
    }
    {
      const parentId = 'parentId' in values ? values.parentId : current?.parentId
      if (parentId != null && (await uow.order.findById(parentId as number)) === null)
        errors.push({ field: 'parentId', message: 'no Order has this key' })
    }
    {
      const kindCode = 'kindCode' in values ? values.kindCode : current?.kindCode
      const kindDay = 'kindDay' in values ? values.kindDay : current?.kindDay
      if (kindCode != null && kindDay != null && (await uow.kinds.findByCodeAndDay(kindCode as string, kindDay as string)) === null)
        errors.push({ field: 'kind_code, kind_day', message: 'no Kind has this key' })
    }
    if (errors.length > 0) throw new ValidationFailedError('Order', errors)
  }

  /** Values that must be unique are not taken by another row. */
  private async checkUnique(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    {
      const customerName = ('customerName' in values ? values.customerName : current?.customerName) as string | null | undefined
      if (customerName != null) {
        const other = await uow.order.findByCustomerName(customerName)
        if (other !== null && (current === null || other.id !== current.id))
          throw new ConflictError('Order', 'customerName is already taken', ['customerName'])
      }
    }
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Order | null): Promise<void> {
    await this.validate(uow, values, current)
    await this.checkUnique(uow, values, current)
  }

  /** The Order with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: number): Promise<Order> {
    const entity = await uow.order.findById(id)
    if (entity === null) throw new NotFoundError('Order', id)
    return entity
  }

  /** The Order as services return it. */
  private static read(entity: Order): OrderRead {
    return { id: entity.id, user: entity.user, group: entity.group, customerName: entity.customerName, class_: entity.class_, metadata: entity.metadata, date: entity.date, time: entity.time, text: entity.text, list: entity.list, str: entity.str, int: entity.int, dueDate: entity.dueDate, closesAt: entity.closesAt, createdAt: entity.createdAt, kindCode: entity.kindCode, kindDay: entity.kindDay, thingId: entity.thingId, parentId: entity.parentId }
  }

  /** Stores a new Order after checking it. */
  async createOrder(data: OrderCreate): Promise<OrderRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.order.insert(Object.assign(new Order(), values))
      return OrderService.read(created)
    })
  }

  /** The Order with this key; NotFoundError when there is none. */
  async getOrder(id: number): Promise<OrderRead> {
    return OrderService.read(await this.find(this.uow, id))
  }

  /** A page of Order, by primary key. */
  async listOrders(offset = 0, limit = 50): Promise<Page<OrderRead>> {
    const page = await this.uow.order.list(offset, limit)
    return { ...page, items: page.items.map((entity) => OrderService.read(entity)) }
  }

  /** Changes the given values of a Order. */
  async updateOrder(id: number, data: OrderUpdate): Promise<OrderRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.order.update(current)
      return OrderService.read(updated)
    })
  }

  /** Deletes a Order. */
  async deleteOrder(id: number): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      if ((await uow.order.listByParentId(current.id)).length > 0) throw new ConflictError('Order', 'rows of Order still point to it', ['Order'])
      await uow.order.delete(current)
    })
  }

  /** The Order with this customerName, or null. */
  async findOrderByCustomerName(customerName: string): Promise<OrderRead | null> {
    const entity = await this.uow.order.findByCustomerName(customerName)
    return entity === null ? null : OrderService.read(entity)
  }

  /** The Order with this thing_id. */
  async listOrdersByThingId(thingId: string): Promise<OrderRead[]> {
    return (await this.uow.order.listByThingId(thingId)).map((entity) => OrderService.read(entity))
  }

  /** The Order with this parentId. */
  async listOrdersByParentId(parentId: number): Promise<OrderRead[]> {
    return (await this.uow.order.listByParentId(parentId)).map((entity) => OrderService.read(entity))
  }

  /** The Order with this kind_code and kind_day. */
  async listOrdersByKindCodeAndKindDay(kindCode: string, kindDay: string): Promise<OrderRead[]> {
    return (await this.uow.order.listByKindCodeAndKindDay(kindCode, kindDay)).map((entity) => OrderService.read(entity))
  }
}

