/** Properties a client may send: the database fills the others */
const FIELDS = new Set(['token', 'small', 'num', 'big', 'price', 'r', 'd', 'flag', 'born', 'opens', 'opensTz', 'at', 'atTz', 'bin', 'data', 'plain', 'feeling', 'tags', 'numbers', 'ip', 'span', 'code', 'note'])

/** Operations on things. Each write runs in its own transaction. */
export class ThingService {
  constructor(private readonly uow: UnitOfWork) {}

  /** Checks the values against the rules of the "things" table, and the rows they point to; throws ValidationFailedError with every problem. */
  private async validate(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Thing | null): Promise<void> {
    const creating = current === null
    const errors: FieldError[] = []
    for (const name of Object.keys(values)) if (!FIELDS.has(name)) errors.push({ field: name, message: 'is not a field of Thing' })
    if (!creating) for (const name of Object.keys(values)) if (['id', 'changed', 'total'].includes(name)) errors.push({ field: name, message: 'cannot be changed' })
    {
      const value = values.token
      if (value == null) {
        if (creating || 'token' in values) errors.push({ field: 'token', message: 'is required' })
      }
    }
    {
      const value = values.small
      if (value == null) {
        if (creating || 'small' in values) errors.push({ field: 'small', message: 'is required' })
      }
    }
    {
      const value = values.big
      if (value == null) {
        if (creating || 'big' in values) errors.push({ field: 'big', message: 'is required' })
      }
    }
    {
      const value = values.price
      if (value == null) {
        if (creating || 'price' in values) errors.push({ field: 'price', message: 'is required' })
      }
    }
    {
      const value = values.r
      if (value == null) {
        if (creating || 'r' in values) errors.push({ field: 'r', message: 'is required' })
      }
    }
    {
      const value = values.flag
      if (value == null) {
        if ('flag' in values && !creating) errors.push({ field: 'flag', message: 'cannot be empty' })
      }
    }
    {
      const value = values.born
      if (value == null) {
        if (creating || 'born' in values) errors.push({ field: 'born', message: 'is required' })
      }
    }
    {
      const value = values.opens
      if (value == null) {
        if (creating || 'opens' in values) errors.push({ field: 'opens', message: 'is required' })
      }
    }
    {
      const value = values.opensTz
      if (value == null) {
        if (creating || 'opensTz' in values) errors.push({ field: 'opens_tz', message: 'is required' })
      }
    }
    {
      const value = values.at
      if (value == null) {
        if (creating || 'at' in values) errors.push({ field: 'at', message: 'is required' })
      }
    }
    {
      const value = values.atTz
      if (value == null) {
        if (creating || 'atTz' in values) errors.push({ field: 'at_tz', message: 'is required' })
      }
    }
    {
      const value = values.bin
      if (value == null) {
        if (creating || 'bin' in values) errors.push({ field: 'bin', message: 'is required' })
      }
    }
    {
      const value = values.data
      if (value == null) {
        if (creating || 'data' in values) errors.push({ field: 'data', message: 'is required' })
      }
    }
    {
      const value = values.feeling
      if (value == null) {
        if (creating || 'feeling' in values) errors.push({ field: 'feeling', message: 'is required' })
      }
    }
    {
      const value = values.tags
      if (value == null) {
        if (creating || 'tags' in values) errors.push({ field: 'tags', message: 'is required' })
      }
    }
    {
      const value = values.code
      if (value == null) {
        if (creating || 'code' in values) errors.push({ field: 'code', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 5) errors.push({ field: 'code', message: 'is longer than 5 characters' })
      }
    }
