  }

  /** The Thing as services return it. */
  private static read(entity: Thing): ThingRead {
    return { id: entity.id, small: entity.small, num: entity.num, big: entity.big, price: entity.price, r: entity.r, d: entity.d, flag: entity.flag, born: entity.born, opens: entity.opens, opensTz: entity.opensTz, at: entity.at, atTz: entity.atTz, bin: entity.bin, data: entity.data, plain: entity.plain, feeling: entity.feeling, tags: entity.tags, numbers: entity.numbers, ip: entity.ip, span: entity.span, code: entity.code, note: entity.note, changed: entity.changed, total: entity.total }
