  }

  /** A page of things, by primary key. */
  async listThings(offset = 0, limit = 50): Promise<Page<ThingRead>> {
    const page = await this.uow.things.list(offset, limit)
    return { ...page, items: page.items.map((entity) => ThingService.read(entity)) }
  }

  /** Changes the given values of a Thing. */
  async updateThing(id: string, data: ThingUpdate): Promise<ThingRead> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(data).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
