/** Tests of the "kinds" table. */
import { describe, expect, it } from 'vitest'
import type { KindCreate } from '../src/dtos/kind.js'
import { NotFoundError, ValidationFailedError } from '../src/errors.js'
import { KindService } from '../src/services/kind.js'
import { MemoryUnitOfWork } from '../src/unit-of-work.js'
import { useTestDatabase } from './database.js'
import { addKind, newKind } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const sqlUow = useTestDatabase()

describe('kinds repository', () => {
  it('is stored and read back', async () => {
    const uow = sqlUow()
    const stored = await addKind(uow, 1)
    const found = await uow.kinds.findByCodeAndDay(stored.code, stored.day)
    expect(found).not.toBeNull()
    expect(found!.code).toEqual(stored.code)
    expect(found!.day).toEqual(stored.day)
  })

  it('lists rows by key', async () => {
    const uow = sqlUow()
    await addKind(uow, 1)
    await addKind(uow, 2)
    const page = await uow.kinds.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = sqlUow()
    const stored = await addKind(uow, 1)
    stored.label = 'changed'
    await uow.kinds.update(stored)
    const found = await uow.kinds.findByCodeAndDay(stored.code, stored.day)
    expect(found?.label).toBe('changed')
  })

  it('is deleted', async () => {
    const uow = sqlUow()
    const stored = await addKind(uow, 1)
    await uow.kinds.delete(stored)
    expect(await uow.kinds.findByCodeAndDay(stored.code, stored.day)).toBeNull()
  })
})

describe('KindService', () => {
  it('creates a valid row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new KindService(uow)
    const n = 100
    const created = await service.createKind(pick<KindCreate>(newKind(1), CREATE_FIELDS))
    const found = await service.getKind(created.code, created.day)
    expect(found.code).toEqual(created.code)
    expect(found.day).toEqual(created.day)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new KindService(uow)
    const n = 100
    const error: unknown = await service.createKind({ ...pick<KindCreate>(newKind(1), CREATE_FIELDS), code: null } as unknown as KindCreate).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['code'])
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new KindService(uow)
    await expect(service.getKind('missing', 'missing')).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new KindService(uow)
    const n = 100
    const created = await service.createKind(pick<KindCreate>(newKind(1), CREATE_FIELDS))
    const updated = await service.updateKind(created.code, created.day, { label: 'changed' })
    expect(updated.label).toBe('changed')
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new KindService(uow)
    const n = 100
    const created = await service.createKind(pick<KindCreate>(newKind(1), CREATE_FIELDS))
    await service.deleteKind(created.code, created.day)
    await expect(service.getKind(created.code, created.day)).rejects.toBeInstanceOf(NotFoundError)
  })
})

/** Fields of the create DTO */
const CREATE_FIELDS = ['code', 'day', 'label']

/** The values a DTO takes, from a row the factories made. */
function pick<T>(row: object, fields: readonly string[]): T {
  return Object.fromEntries(Object.entries(row).filter(([name]) => fields.includes(name))) as T
}

