import { describe, expect, it } from 'vitest'
import type { OrderCreate } from '../src/dtos/order.js'
import { ConflictError, NotFoundError, ValidationFailedError } from '../src/errors.js'
import { OrderService } from '../src/services/order.js'
import { MemoryUnitOfWork } from '../src/unit-of-work.js'
import { useTestDatabase } from './database.js'
import { addKind, addOrder, addThing, newOrder } from './factories.js'

/** The repositories over the test database, opened empty for every test */
const sqlUow = useTestDatabase()

describe('Order repository', () => {
  it('is stored and read back', async () => {
    const uow = sqlUow()
    const stored = await addOrder(uow, 1)
    const found = await uow.order.findById(stored.id)
    expect(found).not.toBeNull()
    expect(found!.id).toEqual(stored.id)
    expect(await uow.order.findByCustomerName(stored.customerName)).not.toBeNull()
    if (stored.thingId != null) expect(await uow.order.listByThingId(stored.thingId)).toHaveLength(1)
    if (stored.parentId != null) expect(await uow.order.listByParentId(stored.parentId)).toHaveLength(1)
    if (stored.kindCode != null && stored.kindDay != null) expect(await uow.order.listByKindCodeAndKindDay(stored.kindCode, stored.kindDay)).toHaveLength(1)
  })

  it('lists rows by key', async () => {
    const uow = sqlUow()
    await addOrder(uow, 1)
    await addOrder(uow, 2)
    const page = await uow.order.list(0, 1)
    expect(page.total).toBe(2)
    expect(page.items).toHaveLength(1)
  })

  it('stores the changes', async () => {
    const uow = sqlUow()
    const stored = await addOrder(uow, 1)
    stored.user = 'changed'
    await uow.order.update(stored)
    const found = await uow.order.findById(stored.id)
    expect(found?.user).toBe('changed')
  })

  it('is deleted', async () => {
    const uow = sqlUow()
    const stored = await addOrder(uow, 1)
    await uow.order.delete(stored)
    expect(await uow.order.findById(stored.id)).toBeNull()
  })
})

describe('OrderService', () => {
  it('creates a valid row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const created = await service.createOrder(pick<OrderCreate>(newOrder(1, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day }), CREATE_FIELDS))
    const found = await service.getOrder(created.id)
    expect(found.id).toEqual(created.id)
  })

  it('refuses a missing value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const error: unknown = await service.createOrder({ ...pick<OrderCreate>(newOrder(1, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day }), CREATE_FIELDS), user: null } as unknown as OrderCreate).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toEqual(['user'])
  })

  it('refuses a repeated unique value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const first = await service.createOrder(pick<OrderCreate>(newOrder(1, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day }), CREATE_FIELDS))
    await expect(service.createOrder(pick<OrderCreate>(newOrder(2, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day, customerName: first.customerName }), CREATE_FIELDS))).rejects.toBeInstanceOf(ConflictError)
  })

  it('keeps its own unique value', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const created = await service.createOrder(pick<OrderCreate>(newOrder(1, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day }), CREATE_FIELDS))
    await service.updateOrder(created.id, { customerName: created.customerName })
  })

  it('refuses a missing parent', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const error: unknown = await service.createOrder(pick<OrderCreate>(newOrder(1, { parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day, thingId: '00000000-0000-4000-8000-000000999999' }), CREATE_FIELDS)).catch((caught: unknown) => caught)
    expect(error).toBeInstanceOf(ValidationFailedError)
    expect((error as ValidationFailedError).errors.map((item) => item.field)).toContain('thing_id')
  })

  it('says when a row is missing', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    await expect(service.getOrder(999999)).rejects.toBeInstanceOf(NotFoundError)
  })

  it('changes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const created = await service.createOrder(pick<OrderCreate>(newOrder(1, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day }), CREATE_FIELDS))
    const updated = await service.updateOrder(created.id, { user: 'changed' })
    expect(updated.user).toBe('changed')
  })

  it('deletes a row', async () => {
    const uow = new MemoryUnitOfWork()
    const service = new OrderService(uow)
    const n = 100
    const parent0 = await addThing(uow, n)
    const parent1 = await addOrder(uow, n)
    const parent2 = await addKind(uow, n)
    const created = await service.createOrder(pick<OrderCreate>(newOrder(1, { thingId: parent0.id, parentId: parent1.id, kindCode: parent2.code, kindDay: parent2.day }), CREATE_FIELDS))
    await service.deleteOrder(created.id)
    await expect(service.getOrder(created.id)).rejects.toBeInstanceOf(NotFoundError)
  })
})

